#!/usr/bin/env bash

HOST="`hostname | sed -e 's/\([a-zA-Z0-9\-]*\).*/\1/'`"
USER="`whoami`"
HIM="$USER@$HOST"
WHEN="`date | awk '{
    if (NF==6) { print $1 " "  $2 " " $3 " "  $6 " at " $4 " " $5 }
    else       { print $1 " "  $2 " " $3 " " $7 " at " $4 " " $5 " " $6 }
}'`"

cat >version.c <<!END!
/**
 * Copyright (C) 2015-2026 unfacd works
 *
 * AUTO-GENERATED by version.c.sh — do not edit.
 *
 * Compiled: $WHEN
 * By:        $HIM
 */

#include <ufsrvclilib/version.h>

#define STRINGISE_NX(A) #A
#define STRINGISE(A) STRINGISE_NX(A)

static const char *t_compiled = "$WHEN";
static const char *u_compiled = "$HIM";
static const char *ufsrvclilib_version =
    STRINGISE(UFSRVCLILIB_MAJOR) "."
    STRINGISE(UFSRVCLILIB_MINOR) "."
    STRINGISE(UFSRVCLILIB_PATCH);

const char *UfsrvCliLibVersion(void)           { return ufsrvclilib_version; }
const char *UfsrvCliLibVersionMajor(void)      { return STRINGISE(UFSRVCLILIB_MAJOR); }
const char *UfsrvCliLibVersionMinor(void)      { return STRINGISE(UFSRVCLILIB_MINOR); }
const char *UfsrvCliLibVersionPatch(void)      { return STRINGISE(UFSRVCLILIB_PATCH); }
const char *UfsrvCliLibCompiledTimestamp(void) { return t_compiled; }
const char *UfsrvCliLibCompiledBy(void)        { return u_compiled; }
!END!
